from pathlib import Path
import subprocess

ROOT = Path.cwd()
head = subprocess.check_output(['git','rev-parse','--short','HEAD'], text=True).strip()
if not head.startswith('8c67697'):
    raise SystemExit(f'Expected HEAD 8c67697, found {head}. Stop and have ChatGPT re-inspect.')

def read(rel):
    return (ROOT / rel).read_text(encoding='utf-8')

def write(rel, content):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')

def repl(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected 1 match, found {count}')
    return text.replace(old, new, 1)

write('lib/cosmetics/catalogue.ts', 'export const COSMETIC_CATEGORIES = [\n  "sheet_frame",\n  "chat_frame",\n  "portrait_frame",\n  "profile_background",\n  "pm_frame",\n  "instant_chat_frame",\n  "forum_frame",\n  "action_style",\n  "nameplate",\n  "profile_crest",\n  "action_flourish",\n  "whisper_style",\n  "header_control_frame",\n  "left_panel_frame",\n  "right_panel_frame",\n  "centre_panel_frame",\n  "location_frame",\n  "location_atmosphere",\n] as const;\n\nexport type CosmeticCategory =\n  (typeof COSMETIC_CATEGORIES)[number];\n\nexport const PUBLIC_COSMETIC_CATEGORIES = [\n  "sheet_frame",\n  "chat_frame",\n  "portrait_frame",\n  "profile_background",\n  "pm_frame",\n  "instant_chat_frame",\n  "forum_frame",\n  "action_style",\n  "nameplate",\n  "profile_crest",\n  "action_flourish",\n  "whisper_style",\n] as const satisfies readonly CosmeticCategory[];\n\nexport const PORTAL_ONLY_COSMETICS = [\n  "header_control_frame",\n  "left_panel_frame",\n  "right_panel_frame",\n  "centre_panel_frame",\n  "location_frame",\n  "location_atmosphere",\n] as const satisfies readonly CosmeticCategory[];\n\nexport const COSMETIC_CATEGORY_SET =\n  new Set<string>(COSMETIC_CATEGORIES);\n\nexport const COSMETIC_LABELS:\n  Record<CosmeticCategory, string> = {\n  sheet_frame: "Sheet Frame",\n  chat_frame: "Location Action Frame",\n  portrait_frame: "Portrait Frame",\n  profile_background: "Profile Background",\n  pm_frame: "Private Message Frame",\n  instant_chat_frame: "Instant Chat Frame",\n  forum_frame: "Forum Post Frame",\n  action_style: "Location Action Style",\n  nameplate: "Nameplate",\n  profile_crest: "Profile Crest / Sigil",\n  action_flourish: "Action Flourish",\n  whisper_style: "Whisper Veil",\n  header_control_frame: "Header Control Frame",\n  left_panel_frame: "Left Panel Frame",\n  right_panel_frame: "Right Panel Frame",\n  centre_panel_frame: "Centre Panel Frame",\n  location_frame: "Location Frame",\n  location_atmosphere: "Location Atmosphere",\n};\n\nexport const COSMETIC_PREFERENCE_COLUMN:\n  Record<CosmeticCategory, string> = {\n  sheet_frame: "equipped_sheet_frame_id",\n  chat_frame: "equipped_chat_frame_id",\n  portrait_frame: "equipped_portrait_frame_id",\n  profile_background: "equipped_profile_background_id",\n  pm_frame: "equipped_pm_frame_id",\n  instant_chat_frame: "equipped_instant_chat_frame_id",\n  forum_frame: "equipped_forum_frame_id",\n  action_style: "equipped_action_style_id",\n  nameplate: "equipped_nameplate_id",\n  profile_crest: "equipped_profile_crest_id",\n  action_flourish: "equipped_action_flourish_id",\n  whisper_style: "equipped_whisper_style_id",\n  header_control_frame: "equipped_header_control_frame_id",\n  left_panel_frame: "equipped_left_panel_frame_id",\n  right_panel_frame: "equipped_right_panel_frame_id",\n  centre_panel_frame: "equipped_centre_panel_frame_id",\n  location_frame: "equipped_location_frame_id",\n  location_atmosphere: "equipped_location_atmosphere_id",\n};\n\nexport function isCosmeticCategory(\n  value: string,\n): value is CosmeticCategory {\n  return COSMETIC_CATEGORY_SET.has(value);\n}\n')
write('components/cosmetics/cosmetic-frame-overlay.tsx', 'import type { CSSProperties } from "react";\n\nexport type CosmeticFrameVariant =\n  | "sheet"\n  | "chat"\n  | "portrait"\n  | "message"\n  | "instant"\n  | "forum"\n  | "nameplate"\n  | "panel"\n  | "header";\n\nfunction safeUrl(value: string) {\n  return value.replace(/"/g, "%22");\n}\n\nexport function cosmeticFrameStyle(\n  assetUrl: string | null | undefined,\n  variant: CosmeticFrameVariant,\n): CSSProperties | undefined {\n  if (!assetUrl) return undefined;\n\n  const base: CSSProperties = {\n    boxSizing: "border-box",\n    borderStyle: "solid",\n    borderColor: "transparent",\n    borderImageSource: `url("${safeUrl(assetUrl)}")`,\n    borderImageWidth: "1",\n    borderImageRepeat: "stretch",\n  };\n\n  switch (variant) {\n    case "sheet":\n      return { ...base, borderWidth: "10px", borderImageSlice: "14% 9%" };\n    case "chat":\n      return {\n        ...base,\n        borderWidth: "clamp(9px, 0.9vw, 13px) clamp(11px, 1.2vw, 17px)",\n        borderImageSlice: "15% 9%",\n      };\n    case "portrait":\n      return { ...base, borderWidth: "9px", borderImageSlice: "12% 12%" };\n    case "message":\n      return { ...base, borderWidth: "8px 10px", borderImageSlice: "15% 9%" };\n    case "instant":\n      return { ...base, borderWidth: "6px 8px", borderImageSlice: "15% 10%" };\n    case "forum":\n      return { ...base, borderWidth: "10px", borderImageSlice: "12% 8%" };\n    case "nameplate":\n      return { ...base, borderWidth: "5px 9px", borderImageSlice: "18% 10%" };\n    case "panel":\n      return { ...base, borderWidth: "8px", borderImageSlice: "10% 10%" };\n    case "header":\n      return { ...base, borderWidth: "5px", borderImageSlice: "18% 18%" };\n  }\n}\n\nexport function cssImageUrl(\n  assetUrl: string | null | undefined,\n): string {\n  return assetUrl ? `url("${safeUrl(assetUrl)}")` : "none";\n}\n')
write('lib/cosmetics/get-equipped-cosmetic.ts', 'import "server-only";\n\nimport {\n  COSMETIC_PREFERENCE_COLUMN,\n  type CosmeticCategory,\n} from "@/lib/cosmetics/catalogue";\nimport { createAdminClient } from "@/lib/supabase/admin";\n\nexport type EquippedCosmetic = {\n  id: string;\n  name: string;\n  category: CosmeticCategory;\n  assetUrl: string;\n};\n\nexport type EquippedCosmeticMap =\n  Partial<Record<CosmeticCategory, EquippedCosmetic>>;\n\nexport async function getEquippedCosmeticsForCharacters(\n  characterIds: string[],\n  categories: readonly CosmeticCategory[],\n): Promise<Record<string, EquippedCosmeticMap>> {\n  const ids = Array.from(new Set(characterIds.filter(Boolean)));\n  if (!ids.length || !categories.length) return {};\n\n  const admin = createAdminClient();\n  const columns = categories.map(\n    (category) => COSMETIC_PREFERENCE_COLUMN[category],\n  );\n\n  const preferencesResult = await admin\n    .from("character_cosmetic_preferences")\n    .select(["character_id", ...columns].join(","))\n    .in("character_id", ids);\n\n  if (preferencesResult.error) {\n    throw new Error(\n      `Unable to load equipped cosmetics: ${preferencesResult.error.message}`,\n    );\n  }\n\n  const preferences = preferencesResult.data ?? [];\n  const cosmeticIds = Array.from(\n    new Set(\n      preferences.flatMap((row) =>\n        columns\n          .map((column) =>\n            String((row as Record<string, unknown>)[column] ?? ""),\n          )\n          .filter(Boolean),\n      ),\n    ),\n  );\n\n  const result = Object.fromEntries(\n    ids.map((id) => [id, {}]),\n  ) as Record<string, EquippedCosmeticMap>;\n\n  if (!cosmeticIds.length) return result;\n\n  const [itemsResult, entitlementsResult] = await Promise.all([\n    admin\n      .from("cosmetic_items")\n      .select("id, name, category, asset_url, is_active")\n      .in("id", cosmeticIds)\n      .eq("is_active", true),\n    admin\n      .from("character_cosmetic_entitlements")\n      .select("character_id, cosmetic_item_id, enabled")\n      .in("character_id", ids)\n      .in("cosmetic_item_id", cosmeticIds)\n      .eq("enabled", true),\n  ]);\n\n  const error = itemsResult.error ?? entitlementsResult.error;\n  if (error) {\n    throw new Error(`Unable to validate equipped cosmetics: ${error.message}`);\n  }\n\n  const items = new Map(\n    (itemsResult.data ?? []).map((item) => [item.id, item]),\n  );\n\n  const enabled = new Set(\n    (entitlementsResult.data ?? []).map(\n      (row) => `${row.character_id}:${row.cosmetic_item_id}`,\n    ),\n  );\n\n  for (const row of preferences) {\n    const characterId = String(row.character_id);\n\n    for (const category of categories) {\n      const column = COSMETIC_PREFERENCE_COLUMN[category];\n      const cosmeticId = String(\n        (row as Record<string, unknown>)[column] ?? "",\n      );\n\n      if (\n        !cosmeticId ||\n        !enabled.has(`${characterId}:${cosmeticId}`)\n      ) {\n        continue;\n      }\n\n      const item = items.get(cosmeticId);\n      if (\n        !item ||\n        item.category !== category ||\n        !item.asset_url\n      ) {\n        continue;\n      }\n\n      result[characterId][category] = {\n        id: item.id,\n        name: item.name,\n        category,\n        assetUrl: item.asset_url,\n      };\n    }\n  }\n\n  return result;\n}\n\nexport async function getEquippedCosmetics(\n  characterId: string,\n  categories: readonly CosmeticCategory[],\n): Promise<EquippedCosmeticMap> {\n  const result = await getEquippedCosmeticsForCharacters(\n    [characterId],\n    categories,\n  );\n  return result[characterId] ?? {};\n}\n\nexport async function getEquippedCosmetic(\n  characterId: string,\n  category: CosmeticCategory,\n): Promise<EquippedCosmetic | null> {\n  const cosmetics = await getEquippedCosmetics(\n    characterId,\n    [category],\n  );\n  return cosmetics[category] ?? null;\n}\n')
write('app/api/cosmetics/equipped/route.ts', 'import { NextRequest, NextResponse } from "next/server";\n\nimport {\n  PUBLIC_COSMETIC_CATEGORIES,\n  type CosmeticCategory,\n} from "@/lib/cosmetics/catalogue";\nimport {\n  getEquippedCosmeticsForCharacters,\n} from "@/lib/cosmetics/get-equipped-cosmetic";\nimport { createClient } from "@/lib/supabase/server";\n\nexport const dynamic = "force-dynamic";\n\nconst UUID =\n  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;\n\nconst PUBLIC_SET = new Set<string>(PUBLIC_COSMETIC_CATEGORIES);\n\nexport async function GET(request: NextRequest) {\n  const supabase = await createClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    return NextResponse.json({ error: "Not authorised." }, { status: 401 });\n  }\n\n  const ids = Array.from(\n    new Set(\n      (request.nextUrl.searchParams.get("ids") ?? "")\n        .split(",")\n        .map((value) => value.trim())\n        .filter((value) => UUID.test(value)),\n    ),\n  ).slice(0, 100);\n\n  const requested = (request.nextUrl.searchParams.get("categories") ?? "")\n    .split(",")\n    .map((value) => value.trim())\n    .filter(\n      (value): value is CosmeticCategory =>\n        PUBLIC_SET.has(value),\n    );\n\n  const categories =\n    requested.length > 0\n      ? requested\n      : [...PUBLIC_COSMETIC_CATEGORIES];\n\n  try {\n    const cosmetics = await getEquippedCosmeticsForCharacters(\n      ids,\n      categories,\n    );\n\n    return NextResponse.json({ cosmetics });\n  } catch (error) {\n    return NextResponse.json(\n      {\n        error:\n          error instanceof Error\n            ? error.message\n            : "Unable to load cosmetics.",\n      },\n      { status: 500 },\n    );\n  }\n}\n')
write('components/cosmetics/cosmetic-runtime.tsx', '"use client";\n\nimport { useEffect, useRef } from "react";\n\nimport {\n  PUBLIC_COSMETIC_CATEGORIES,\n  type CosmeticCategory,\n} from "@/lib/cosmetics/catalogue";\n\ntype PublicCosmeticMap =\n  Partial<Record<CosmeticCategory, string>>;\n\nconst SURFACE_RULES: Record<\n  string,\n  CosmeticCategory[]\n> = {\n  sheet: ["profile_background"],\n  portrait: ["portrait_frame"],\n  nameplate: ["nameplate", "profile_crest"],\n  action: ["action_style", "action_flourish"],\n  whisper: ["whisper_style"],\n  pm: ["pm_frame"],\n  instant: ["instant_chat_frame"],\n  forum: ["forum_frame"],\n};\n\nfunction cssUrl(value: string) {\n  return `url("${value.replace(/"/g, "%22")}")`;\n}\n\nfunction applySurface(\n  element: HTMLElement,\n  cosmetics: PublicCosmeticMap,\n) {\n  const surface = element.dataset.cosmeticSurface ?? "";\n  const categories = SURFACE_RULES[surface] ?? [];\n\n  for (const category of categories) {\n    const asset = cosmetics[category];\n    const cssName = `--sep-cosmetic-${category.replaceAll("_", "-")}`;\n\n    if (asset) {\n      element.style.setProperty(cssName, cssUrl(asset));\n      element.dataset[`has${category\n        .split("_")\n        .map((part) => part[0].toUpperCase() + part.slice(1))\n        .join("")}`] = "true";\n    } else {\n      element.style.removeProperty(cssName);\n    }\n  }\n}\n\nexport function CosmeticRuntime() {\n  const timer = useRef<number | null>(null);\n\n  useEffect(() => {\n    let cancelled = false;\n\n    async function scan() {\n      const elements = Array.from(\n        document.querySelectorAll<HTMLElement>(\n          "[data-cosmetic-character-id][data-cosmetic-surface]",\n        ),\n      );\n\n      const ids = Array.from(\n        new Set(\n          elements\n            .map((element) => element.dataset.cosmeticCharacterId ?? "")\n            .filter(Boolean),\n        ),\n      );\n\n      if (!ids.length) return;\n\n      try {\n        const response = await fetch(\n          `/api/cosmetics/equipped?ids=${encodeURIComponent(\n            ids.join(","),\n          )}&categories=${encodeURIComponent(\n            PUBLIC_COSMETIC_CATEGORIES.join(","),\n          )}`,\n          { cache: "no-store" },\n        );\n\n        const data = (await response.json()) as {\n          cosmetics?: Record<\n            string,\n            Record<string, { assetUrl?: string }>\n          >;\n        };\n\n        if (!response.ok || cancelled) return;\n\n        const resolved: Record<string, PublicCosmeticMap> = {};\n\n        for (const [characterId, entries] of Object.entries(\n          data.cosmetics ?? {},\n        )) {\n          resolved[characterId] = {};\n\n          for (const [category, entry] of Object.entries(entries)) {\n            if (entry.assetUrl) {\n              resolved[characterId][\n                category as CosmeticCategory\n              ] = entry.assetUrl;\n            }\n          }\n        }\n\n        for (const element of elements) {\n          const characterId =\n            element.dataset.cosmeticCharacterId ?? "";\n          applySurface(\n            element,\n            resolved[characterId] ?? {},\n          );\n        }\n      } catch (error) {\n        console.error("Unable to apply cosmetics:", error);\n      }\n    }\n\n    function schedule() {\n      if (timer.current !== null) {\n        window.clearTimeout(timer.current);\n      }\n      timer.current = window.setTimeout(() => {\n        void scan();\n      }, 80);\n    }\n\n    const observer = new MutationObserver(schedule);\n    observer.observe(document.body, {\n      childList: true,\n      subtree: true,\n    });\n\n    schedule();\n\n    const interval = window.setInterval(() => {\n      void scan();\n    }, 30000);\n\n    window.addEventListener("focus", schedule);\n\n    return () => {\n      cancelled = true;\n      observer.disconnect();\n      window.clearInterval(interval);\n      window.removeEventListener("focus", schedule);\n      if (timer.current !== null) {\n        window.clearTimeout(timer.current);\n      }\n    };\n  }, []);\n\n  return (\n    <style>{`\n      [data-cosmetic-surface="portrait"][data-has-portrait-frame="true"] {\n        box-sizing: border-box;\n        border: 9px solid transparent !important;\n        border-image-source: var(--sep-cosmetic-portrait-frame);\n        border-image-slice: 12%;\n        border-image-width: 1;\n        border-image-repeat: stretch;\n      }\n\n      [data-cosmetic-surface="nameplate"] {\n        position: relative;\n        isolation: isolate;\n      }\n\n      [data-cosmetic-surface="nameplate"][data-has-nameplate="true"] {\n        display: inline-block;\n        border: 5px 9px solid transparent;\n        border-image-source: var(--sep-cosmetic-nameplate);\n        border-image-slice: 18% 10%;\n        border-image-width: 1;\n        border-image-repeat: stretch;\n      }\n\n      [data-cosmetic-surface="nameplate"][data-has-profile-crest="true"]::after {\n        content: "";\n        position: absolute;\n        z-index: 2;\n        width: 28px;\n        height: 28px;\n        right: -18px;\n        top: 50%;\n        transform: translateY(-50%);\n        background-image: var(--sep-cosmetic-profile-crest);\n        background-size: contain;\n        background-position: center;\n        background-repeat: no-repeat;\n        pointer-events: none;\n      }\n\n      [data-cosmetic-surface="sheet"][data-has-profile-background="true"] {\n        background-image:\n          linear-gradient(rgba(0,0,0,.72), rgba(0,0,0,.72)),\n          var(--sep-cosmetic-profile-background);\n        background-size: cover;\n        background-position: center;\n        background-repeat: no-repeat;\n      }\n\n      [data-cosmetic-surface="pm"][data-has-pm-frame="true"] {\n        border: 8px 10px solid transparent !important;\n        border-image-source: var(--sep-cosmetic-pm-frame);\n        border-image-slice: 15% 9%;\n        border-image-width: 1;\n        border-image-repeat: stretch;\n      }\n\n      [data-cosmetic-surface="instant"][data-has-instant-chat-frame="true"] {\n        border: 6px 8px solid transparent !important;\n        border-image-source: var(--sep-cosmetic-instant-chat-frame);\n        border-image-slice: 15% 10%;\n        border-image-width: 1;\n        border-image-repeat: stretch;\n      }\n\n      [data-cosmetic-surface="forum"][data-has-forum-frame="true"] {\n        border: 10px solid transparent !important;\n        border-image-source: var(--sep-cosmetic-forum-frame);\n        border-image-slice: 12% 8%;\n        border-image-width: 1;\n        border-image-repeat: stretch;\n      }\n\n      [data-cosmetic-surface="action"] {\n        isolation: isolate;\n      }\n\n      [data-cosmetic-surface="action"][data-has-action-style="true"] {\n        background-image: var(--sep-cosmetic-action-style);\n        background-position: center bottom;\n        background-repeat: no-repeat;\n        background-size: 100% auto;\n      }\n\n      [data-cosmetic-surface="action"][data-has-action-flourish="true"]::after {\n        content: "";\n        position: absolute;\n        z-index: 1;\n        right: 4px;\n        bottom: 0;\n        width: min(260px, 38%);\n        height: 34px;\n        background-image: var(--sep-cosmetic-action-flourish);\n        background-position: right bottom;\n        background-repeat: no-repeat;\n        background-size: contain;\n        pointer-events: none;\n      }\n\n      [data-cosmetic-surface="whisper"] {\n        isolation: isolate;\n      }\n\n      [data-cosmetic-surface="whisper"][data-has-whisper-style="true"]::before {\n        content: "";\n        position: absolute;\n        inset: 0;\n        z-index: 0;\n        background-image: var(--sep-cosmetic-whisper-style);\n        background-position: center;\n        background-repeat: no-repeat;\n        background-size: 100% 100%;\n        opacity: .72;\n        pointer-events: none;\n      }\n\n      [data-cosmetic-surface="whisper"][data-has-whisper-style="true"] > * {\n        position: relative;\n        z-index: 1;\n      }\n    `}</style>\n  );\n}\n')
write('app/(portal)/cosmetics/actions.ts', '"use server";\n\nimport { revalidatePath } from "next/cache";\n\nimport {\n  COSMETIC_PREFERENCE_COLUMN,\n  isCosmeticCategory,\n  type CosmeticCategory,\n} from "@/lib/cosmetics/catalogue";\nimport { createAdminClient } from "@/lib/supabase/admin";\nimport { createClient } from "@/lib/supabase/server";\n\nfunction readSlot(\n  value: FormDataEntryValue | null,\n): CosmeticCategory {\n  const slot = String(value ?? "");\n  if (isCosmeticCategory(slot)) return slot;\n  throw new Error("Invalid cosmetic slot.");\n}\n\nexport async function setEquippedCosmetic(\n  formData: FormData,\n) {\n  const supabase = await createClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) throw new Error("You must be signed in.");\n\n  const characterResult = await supabase\n    .from("characters")\n    .select("id")\n    .eq("user_id", user.id)\n    .maybeSingle();\n\n  if (characterResult.error || !characterResult.data) {\n    throw new Error(\n      characterResult.error?.message ?? "Character not found.",\n    );\n  }\n\n  const character = characterResult.data;\n  const slot = readSlot(formData.get("slot"));\n  const cosmeticIdRaw = String(\n    formData.get("cosmeticId") ?? "",\n  ).trim();\n  const cosmeticId = cosmeticIdRaw || null;\n  const admin = createAdminClient();\n\n  if (cosmeticId) {\n    const [cosmeticResult, entitlementResult] = await Promise.all([\n      admin\n        .from("cosmetic_items")\n        .select("id, category, is_active")\n        .eq("id", cosmeticId)\n        .maybeSingle(),\n      admin\n        .from("character_cosmetic_entitlements")\n        .select("enabled")\n        .eq("character_id", character.id)\n        .eq("cosmetic_item_id", cosmeticId)\n        .maybeSingle(),\n    ]);\n\n    if (cosmeticResult.error || !cosmeticResult.data) {\n      throw new Error(\n        cosmeticResult.error?.message ?? "Cosmetic not found.",\n      );\n    }\n\n    if (cosmeticResult.data.is_active !== true) {\n      throw new Error("Inactive cosmetics cannot be equipped.");\n    }\n\n    if (cosmeticResult.data.category !== slot) {\n      throw new Error("That cosmetic does not belong in this slot.");\n    }\n\n    if (\n      entitlementResult.error ||\n      entitlementResult.data?.enabled !== true\n    ) {\n      throw new Error(\n        entitlementResult.error?.message ??\n          "You do not own that cosmetic.",\n      );\n    }\n  }\n\n  const column = COSMETIC_PREFERENCE_COLUMN[slot];\n\n  const preferenceResult = await admin\n    .from("character_cosmetic_preferences")\n    .upsert(\n      {\n        character_id: character.id,\n        [column]: cosmeticId,\n        updated_at: new Date().toISOString(),\n      },\n      { onConflict: "character_id" },\n    );\n\n  if (preferenceResult.error) {\n    throw new Error(\n      `Unable to equip cosmetic: ${preferenceResult.error.message}`,\n    );\n  }\n\n  for (const path of [\n    "/cosmetics",\n    "/character",\n    "/characters",\n    "/game",\n    "/messages",\n    "/forum",\n  ]) {\n    revalidatePath(path);\n  }\n\n  revalidatePath("/", "layout");\n}\n')
write('app/(portal)/cosmetics/page.tsx', 'import { redirect } from "next/navigation";\n\nimport {\n  PlayerCosmeticsManager,\n  type PlayerCosmeticRow,\n} from "@/components/cosmetics/player-cosmetics-manager";\nimport {\n  COSMETIC_CATEGORIES,\n  COSMETIC_PREFERENCE_COLUMN,\n  type CosmeticCategory,\n} from "@/lib/cosmetics/catalogue";\nimport { createClient } from "@/lib/supabase/server";\n\nexport const dynamic = "force-dynamic";\nexport const revalidate = 0;\n\nexport default async function CosmeticsPage() {\n  const supabase = await createClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) redirect("/login");\n\n  const characterResult = await supabase\n    .from("characters")\n    .select("id")\n    .eq("user_id", user.id)\n    .maybeSingle();\n\n  if (characterResult.error || !characterResult.data) {\n    redirect("/");\n  }\n\n  const character = characterResult.data;\n  const preferenceColumns = COSMETIC_CATEGORIES.map(\n    (category) => COSMETIC_PREFERENCE_COLUMN[category],\n  );\n\n  const [entitlementResult, preferenceResult] = await Promise.all([\n    supabase\n      .from("character_cosmetic_entitlements")\n      .select(`\n        cosmetic_item_id,\n        cosmetic:cosmetic_items!character_cosmetic_entitlements_cosmetic_item_id_fkey(\n          id, slug, name, description, category,\n          preview_image_url, asset_url, sort_order, is_active\n        )\n      `)\n      .eq("character_id", character.id)\n      .eq("enabled", true),\n\n    supabase\n      .from("character_cosmetic_preferences")\n      .select(preferenceColumns.join(","))\n      .eq("character_id", character.id)\n      .maybeSingle(),\n  ]);\n\n  const error = entitlementResult.error ?? preferenceResult.error;\n  if (error) {\n    throw new Error(`Unable to load Cosmetics: ${error.message}`);\n  }\n\n  const cosmetics = (entitlementResult.data ?? [])\n    .map((entry) => {\n      const relation = Array.isArray(entry.cosmetic)\n        ? entry.cosmetic[0]\n        : entry.cosmetic;\n\n      if (\n        !relation ||\n        relation.is_active !== true ||\n        !COSMETIC_CATEGORIES.includes(\n          relation.category as CosmeticCategory,\n        )\n      ) {\n        return null;\n      }\n\n      return {\n        id: String(relation.id),\n        slug: String(relation.slug),\n        name: String(relation.name),\n        description: relation.description ?? "",\n        category: relation.category as CosmeticCategory,\n        previewImageUrl: relation.preview_image_url ?? null,\n        assetUrl: relation.asset_url ?? null,\n        sortOrder: Number(relation.sort_order ?? 0),\n      } satisfies PlayerCosmeticRow;\n    })\n    .filter((entry): entry is PlayerCosmeticRow => entry !== null)\n    .sort(\n      (a, b) =>\n        a.sortOrder - b.sortOrder ||\n        a.name.localeCompare(b.name),\n    );\n\n  const equipped: Partial<\n    Record<CosmeticCategory, string | null>\n  > = {};\n\n  for (const category of COSMETIC_CATEGORIES) {\n    const column = COSMETIC_PREFERENCE_COLUMN[category];\n    equipped[category] =\n      String(\n        (preferenceResult.data as Record<string, unknown> | null)?.[\n          column\n        ] ?? "",\n      ) || null;\n  }\n\n  return (\n    <main className="p-5 sm:p-7 lg:p-9">\n      <div className="mx-auto max-w-7xl">\n        <p className="text-[9px] uppercase tracking-[0.28em] text-[rgb(var(--sep-colour-8c704b))]">\n          Premium\n        </p>\n        <h1 className="mt-2 font-serif text-4xl text-[rgb(var(--sep-colour-ead5ac))]">\n          Cosmetics\n        </h1>\n        <p className="mt-3 max-w-3xl text-sm leading-7 text-[rgb(var(--sep-colour-a99b89))]">\n          Equip character-facing and portal-facing visual treatments. You can own many items, but only one item can be equipped in each slot.\n        </p>\n\n        <PlayerCosmeticsManager\n          initialCosmetics={cosmetics}\n          initialEquipped={equipped}\n        />\n      </div>\n    </main>\n  );\n}\n')
write('components/cosmetics/player-cosmetics-manager.tsx', '"use client";\n\nimport { useMemo, useState, useTransition } from "react";\n\nimport { setEquippedCosmetic } from "@/app/(portal)/cosmetics/actions";\nimport {\n  COSMETIC_CATEGORIES,\n  COSMETIC_LABELS,\n  type CosmeticCategory,\n} from "@/lib/cosmetics/catalogue";\n\nexport type PlayerCosmeticRow = {\n  id: string;\n  slug: string;\n  name: string;\n  description: string;\n  category: CosmeticCategory;\n  previewImageUrl: string | null;\n  assetUrl: string | null;\n  sortOrder: number;\n};\n\nexport function PlayerCosmeticsManager({\n  initialCosmetics,\n  initialEquipped,\n}: {\n  initialCosmetics: PlayerCosmeticRow[];\n  initialEquipped: Partial<\n    Record<CosmeticCategory, string | null>\n  >;\n}) {\n  const firstAvailable =\n    COSMETIC_CATEGORIES.find((category) =>\n      initialCosmetics.some((item) => item.category === category),\n    ) ?? "sheet_frame";\n\n  const [category, setCategory] =\n    useState<CosmeticCategory>(firstAvailable);\n  const [equipped, setEquipped] = useState(initialEquipped);\n  const [message, setMessage] = useState("");\n  const [failed, setFailed] = useState(false);\n  const [pending, startTransition] = useTransition();\n\n  const visible = useMemo(\n    () =>\n      initialCosmetics.filter(\n        (item) => item.category === category,\n      ),\n    [initialCosmetics, category],\n  );\n\n  const equippedId = equipped[category] ?? null;\n\n  function changeEquipped(cosmeticId: string | null) {\n    setMessage("");\n    setFailed(false);\n\n    const data = new FormData();\n    data.set("slot", category);\n    data.set("cosmeticId", cosmeticId ?? "");\n\n    startTransition(async () => {\n      try {\n        await setEquippedCosmetic(data);\n        setEquipped((current) => ({\n          ...current,\n          [category]: cosmeticId,\n        }));\n        setMessage(\n          cosmeticId ? "Cosmetic equipped." : "Cosmetic unequipped.",\n        );\n      } catch (error) {\n        setFailed(true);\n        setMessage(\n          error instanceof Error\n            ? error.message\n            : "Unable to update cosmetic.",\n        );\n      }\n    });\n  }\n\n  return (\n    <section className="mt-7 overflow-hidden border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-15100d))]">\n      <header className="border-b border-[rgb(var(--sep-colour-60482e))]/35 bg-[rgb(var(--sep-colour-100c09))] px-5 py-4">\n        <p className="text-[8px] uppercase tracking-[0.22em] text-[rgb(var(--sep-colour-a68152))]">\n          Your collection\n        </p>\n        <h2 className="mt-1 font-serif text-2xl text-[rgb(var(--sep-colour-dfc99f))]">\n          Equipped Appearance\n        </h2>\n      </header>\n\n      <div className="border-b border-[rgb(var(--sep-colour-60482e))]/35 p-4">\n        <select\n          value={category}\n          onChange={(event) => {\n            setCategory(event.target.value as CosmeticCategory);\n            setMessage("");\n          }}\n          className="w-full border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-100c09))] px-3 py-2.5 text-sm text-[rgb(var(--sep-colour-d7c4a5))]"\n        >\n          {COSMETIC_CATEGORIES.map((value) => (\n            <option key={value} value={value}>\n              {COSMETIC_LABELS[value]}\n            </option>\n          ))}\n        </select>\n      </div>\n\n      {message ? (\n        <div\n          className={[\n            "mx-5 mt-5 border px-4 py-3 text-xs",\n            failed\n              ? "border-red-800/55 text-red-200"\n              : "border-[rgb(var(--sep-colour-56754f))]/55 text-[rgb(var(--sep-colour-c5d7bd))]",\n          ].join(" ")}\n        >\n          {message}\n        </div>\n      ) : null}\n\n      <div className="p-5">\n        {equippedId ? (\n          <div className="mb-5 flex flex-wrap items-center justify-between gap-3 border border-[rgb(var(--sep-colour-765937))]/45 bg-[rgb(var(--sep-colour-21170f))] px-4 py-3">\n            <p className="font-serif text-lg text-[rgb(var(--sep-colour-dfc99f))]">\n              {initialCosmetics.find((item) => item.id === equippedId)\n                ?.name ?? "Equipped cosmetic"}\n            </p>\n            <button\n              type="button"\n              disabled={pending}\n              onClick={() => changeEquipped(null)}\n              className="border border-[rgb(var(--sep-colour-765937))]/55 px-4 py-2 text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-cbb28a))] disabled:opacity-45"\n            >\n              Unequip\n            </button>\n          </div>\n        ) : null}\n\n        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">\n          {visible.map((item) => {\n            const isEquipped = item.id === equippedId;\n\n            return (\n              <article\n                key={item.id}\n                className={[\n                  "overflow-hidden border bg-[rgb(var(--sep-colour-100c09))]",\n                  isEquipped\n                    ? "border-[rgb(var(--sep-colour-987344))]"\n                    : "border-[rgb(var(--sep-colour-59432c))]/45",\n                ].join(" ")}\n              >\n                <div className="flex h-44 items-center justify-center bg-[rgb(var(--sep-colour-0d0a08))] p-4">\n                  {item.previewImageUrl ?? item.assetUrl ? (\n                    <img\n                      src={item.previewImageUrl ?? item.assetUrl ?? ""}\n                      alt=""\n                      className="max-h-full max-w-full object-contain"\n                    />\n                  ) : null}\n                </div>\n\n                <div className="p-4">\n                  <p className="text-[7px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-806b50))]">\n                    {COSMETIC_LABELS[item.category]}\n                  </p>\n                  <h3 className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-dfc99f))]">\n                    {item.name}\n                  </h3>\n                  <p className="mt-2 min-h-10 text-[10px] leading-5 text-[rgb(var(--sep-colour-8f8271))]">\n                    {item.description || "Collectible Sepulchria cosmetic."}\n                  </p>\n                  <button\n                    type="button"\n                    disabled={pending || isEquipped}\n                    onClick={() => changeEquipped(item.id)}\n                    className="mt-4 w-full border border-[rgb(var(--sep-colour-987344))] bg-[rgb(var(--sep-colour-3b2919))] px-4 py-2.5 text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-efd6a8))] disabled:opacity-45"\n                  >\n                    {isEquipped\n                      ? "Equipped"\n                      : pending\n                        ? "Working..."\n                        : "Equip"}\n                  </button>\n                </div>\n              </article>\n            );\n          })}\n        </div>\n\n        {visible.length === 0 ? (\n          <p className="border border-dashed border-[rgb(var(--sep-colour-59432c))]/40 px-5 py-10 text-center font-serif text-lg text-[rgb(var(--sep-colour-bba17a))]">\n            No {COSMETIC_LABELS[category].toLowerCase()} owned yet.\n          </p>\n        ) : null}\n      </div>\n    </section>\n  );\n}\n')
write('app/(portal)/admin/characters/cosmetic-actions.ts', '"use server";\n\nimport { revalidatePath } from "next/cache";\n\nimport { requireStaffCapability } from "@/lib/auth/require-staff";\nimport {\n  COSMETIC_LABELS,\n  isCosmeticCategory,\n} from "@/lib/cosmetics/catalogue";\nimport { createPremiumFeatureGrantNotification } from "@/lib/premium-features/notifications";\nimport { createAdminClient } from "@/lib/supabase/admin";\n\nconst SOURCES = new Set([\n  "paid",\n  "staff",\n  "reward",\n  "promotion",\n  "gift",\n  "event",\n]);\n\nfunction required(formData: FormData, key: string) {\n  const value = String(formData.get(key) ?? "").trim();\n  if (!value) throw new Error(`${key} is required.`);\n  return value;\n}\n\nexport async function setCharacterCosmeticEntitlement(\n  formData: FormData,\n) {\n  const staff = await requireStaffCapability("character_economy");\n  const characterId = required(formData, "characterId");\n  const cosmeticItemId = required(formData, "cosmeticItemId");\n  const enabled =\n    String(formData.get("enabled") ?? "false") === "true";\n  const source = String(formData.get("source") ?? "staff");\n\n  if (!SOURCES.has(source)) {\n    throw new Error("Invalid cosmetic entitlement source.");\n  }\n\n  const note =\n    String(formData.get("note") ?? "").trim().slice(0, 1000) ||\n    null;\n\n  const admin = createAdminClient();\n  const [previousResult, cosmeticResult] = await Promise.all([\n    admin\n      .from("character_cosmetic_entitlements")\n      .select("enabled")\n      .eq("character_id", characterId)\n      .eq("cosmetic_item_id", cosmeticItemId)\n      .maybeSingle(),\n    admin\n      .from("cosmetic_items")\n      .select("id, name, category, is_active")\n      .eq("id", cosmeticItemId)\n      .maybeSingle(),\n  ]);\n\n  if (previousResult.error) {\n    throw new Error(\n      `Unable to check existing cosmetic ownership: ${previousResult.error.message}`,\n    );\n  }\n\n  if (cosmeticResult.error || !cosmeticResult.data) {\n    throw new Error(\n      cosmeticResult.error?.message ?? "Cosmetic not found.",\n    );\n  }\n\n  const cosmetic = cosmeticResult.data;\n\n  if (!isCosmeticCategory(cosmetic.category)) {\n    throw new Error("Unsupported cosmetic category.");\n  }\n\n  if (enabled && cosmetic.is_active !== true) {\n    throw new Error("Inactive cosmetics cannot be granted.");\n  }\n\n  const wasEnabled = previousResult.data?.enabled === true;\n  const now = new Date().toISOString();\n\n  const update = await admin\n    .from("character_cosmetic_entitlements")\n    .upsert(\n      {\n        character_id: characterId,\n        cosmetic_item_id: cosmeticItemId,\n        enabled,\n        source,\n        note,\n        granted_at: now,\n        granted_by: staff.userId,\n        updated_at: now,\n      },\n      { onConflict: "character_id,cosmetic_item_id" },\n    );\n\n  if (update.error) {\n    throw new Error(\n      `Unable to update cosmetic ownership: ${update.error.message}`,\n    );\n  }\n\n  if (enabled && !wasEnabled) {\n    try {\n      await createPremiumFeatureGrantNotification({\n        characterId,\n        createdBy: staff.userId,\n        title: `Premium cosmetic unlocked: ${cosmetic.name}`,\n        body: `You have unlocked ${cosmetic.name} (${COSMETIC_LABELS[cosmetic.category]}). Equip it from your Cosmetics collection.`,\n        href: "/cosmetics",\n      });\n    } catch (notificationError) {\n      console.error(\n        "Cosmetic ownership was granted, but its notification could not be created:",\n        notificationError,\n      );\n    }\n  }\n\n  for (const path of [\n    `/admin/characters/${characterId}/premium-features`,\n    "/character",\n    "/characters",\n    "/game",\n    "/messages",\n    "/forum",\n  ]) {\n    revalidatePath(path);\n  }\n\n  revalidatePath("/", "layout");\n}\n')
write('components/admin/admin-character-cosmetics-access.tsx', 'import {\n  setCharacterCosmeticEntitlement,\n} from "@/app/(portal)/admin/characters/cosmetic-actions";\nimport {\n  COSMETIC_LABELS,\n  type CosmeticCategory,\n} from "@/lib/cosmetics/catalogue";\n\nexport type CharacterCosmeticRow = {\n  id: string;\n  slug: string;\n  name: string;\n  description: string;\n  category: CosmeticCategory;\n  preview_image_url: string | null;\n  asset_url: string | null;\n  is_active: boolean;\n};\n\nexport type CharacterCosmeticEntitlementRow = {\n  cosmetic_item_id: string;\n  enabled: boolean;\n  source:\n    | "paid"\n    | "staff"\n    | "reward"\n    | "promotion"\n    | "gift"\n    | "event";\n  note: string | null;\n  granted_at: string;\n  granted_by: string | null;\n  updated_at: string;\n};\n\nexport function AdminCharacterCosmeticsAccess({\n  characterId,\n  cosmetics,\n  entitlements,\n}: {\n  characterId: string;\n  cosmetics: CharacterCosmeticRow[];\n  entitlements: CharacterCosmeticEntitlementRow[];\n}) {\n  const byCosmetic = new Map(\n    entitlements.map((entry) => [entry.cosmetic_item_id, entry]),\n  );\n\n  return (\n    <section className="mt-6 overflow-hidden border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-15100d))]">\n      <div className="border-b border-[rgb(var(--sep-colour-60482e))]/35 bg-[rgb(var(--sep-colour-100c09))] px-5 py-4">\n        <p className="text-[9px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-8c704b))]">\n          Cosmetic access\n        </p>\n        <h2 className="mt-2 font-serif text-2xl text-[rgb(var(--sep-colour-e1c89f))]">\n          Premium Cosmetics\n        </h2>\n      </div>\n\n      <div className="grid gap-px bg-[rgb(var(--sep-colour-4f3b28))]/35 lg:grid-cols-2">\n        {cosmetics.map((cosmetic) => {\n          const entitlement = byCosmetic.get(cosmetic.id);\n          const enabled = entitlement?.enabled === true;\n\n          return (\n            <form\n              key={cosmetic.id}\n              data-admin-premium-feature="true"\n              data-admin-feature-name={cosmetic.name}\n              data-admin-feature-type={`Cosmetic · ${COSMETIC_LABELS[cosmetic.category]}`}\n              action={setCharacterCosmeticEntitlement}\n              className="bg-[rgb(var(--sep-colour-17110d))] p-5"\n            >\n              <input\n                type="hidden"\n                name="characterId"\n                value={characterId}\n              />\n              <input\n                type="hidden"\n                name="cosmeticItemId"\n                value={cosmetic.id}\n              />\n\n              <div className="flex items-start gap-4">\n                <div className="flex h-20 w-20 shrink-0 items-center justify-center overflow-hidden border border-[rgb(var(--sep-colour-59432c))]/45 bg-[rgb(var(--sep-colour-0d0907))] p-2">\n                  {cosmetic.preview_image_url ?? cosmetic.asset_url ? (\n                    <img\n                      src={\n                        cosmetic.preview_image_url ??\n                        cosmetic.asset_url ??\n                        ""\n                      }\n                      alt=""\n                      className="max-h-full max-w-full object-contain"\n                    />\n                  ) : null}\n                </div>\n\n                <div className="min-w-0 flex-1">\n                  <p className="text-[7px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-806b50))]">\n                    {COSMETIC_LABELS[cosmetic.category]}\n                  </p>\n                  <h3 className="mt-1 font-serif text-lg text-[rgb(var(--sep-colour-dfc79c))]">\n                    {cosmetic.name}\n                  </h3>\n                  <p className="mt-2 text-[11px] leading-5 text-[rgb(var(--sep-colour-8f8271))]">\n                    {cosmetic.description}\n                  </p>\n                </div>\n              </div>\n\n              <div className="mt-5 grid gap-4">\n                <select\n                  name="enabled"\n                  defaultValue={enabled ? "true" : "false"}\n                  className="w-full border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-0d0907))] px-3 py-2.5 text-sm text-[rgb(var(--sep-colour-d7c4a5))]"\n                >\n                  <option value="false">Disabled</option>\n                  <option value="true">Enabled</option>\n                </select>\n\n                <select\n                  name="source"\n                  defaultValue={entitlement?.source ?? "staff"}\n                  className="w-full border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-0d0907))] px-3 py-2.5 text-sm text-[rgb(var(--sep-colour-d7c4a5))]"\n                >\n                  <option value="paid">Real-money purchase</option>\n                  <option value="staff">Staff grant</option>\n                  <option value="reward">Reward</option>\n                  <option value="promotion">Promotion</option>\n                  <option value="gift">Gift</option>\n                  <option value="event">Event</option>\n                </select>\n\n                <textarea\n                  name="note"\n                  rows={3}\n                  maxLength={1000}\n                  defaultValue={entitlement?.note ?? ""}\n                  placeholder="Optional staff note"\n                  className="w-full resize-y border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-0d0907))] px-3 py-2.5 text-sm text-[rgb(var(--sep-colour-d7c4a5))]"\n                />\n              </div>\n\n              <div className="mt-5 flex justify-end border-t border-[rgb(var(--sep-colour-5d452d))]/35 pt-4">\n                <button\n                  type="submit"\n                  className="border border-[rgb(var(--sep-colour-8d6d3e))] bg-[rgb(var(--sep-colour-332719))] px-4 py-2 text-[9px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-efd9aa))]"\n                >\n                  Save ownership\n                </button>\n              </div>\n            </form>\n          );\n        })}\n      </div>\n    </section>\n  );\n}\n')
write('cosmetics_full_system_8c67697.sql', "-- Sepulchria full cosmetic system extension.\n-- Run in Supabase SQL Editor after applying the Python patch.\n\nalter table public.cosmetic_items\n  drop constraint if exists cosmetic_items_category_check;\n\nalter table public.cosmetic_items\n  add constraint cosmetic_items_category_check\n  check (\n    category in (\n      'sheet_frame',\n      'chat_frame',\n      'portrait_frame',\n      'profile_background',\n      'pm_frame',\n      'instant_chat_frame',\n      'forum_frame',\n      'action_style',\n      'nameplate',\n      'profile_crest',\n      'action_flourish',\n      'whisper_style',\n      'header_control_frame',\n      'left_panel_frame',\n      'right_panel_frame',\n      'centre_panel_frame',\n      'location_frame',\n      'location_atmosphere'\n    )\n  );\n\nalter table public.character_cosmetic_preferences\n  add column if not exists equipped_portrait_frame_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_profile_background_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_pm_frame_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_instant_chat_frame_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_forum_frame_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_action_style_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_nameplate_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_profile_crest_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_action_flourish_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_whisper_style_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_header_control_frame_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_left_panel_frame_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_right_panel_frame_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_centre_panel_frame_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_location_frame_id uuid references public.cosmetic_items(id) on delete set null,\n  add column if not exists equipped_location_atmosphere_id uuid references public.cosmetic_items(id) on delete set null;\n\ncreate or replace function public.validate_extended_cosmetic_preferences()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  slot record;\n  actual_category text;\n  owned boolean;\nbegin\n  for slot in\n    select *\n    from (\n      values\n        ('sheet_frame', new.equipped_sheet_frame_id),\n        ('chat_frame', new.equipped_chat_frame_id),\n        ('portrait_frame', new.equipped_portrait_frame_id),\n        ('profile_background', new.equipped_profile_background_id),\n        ('pm_frame', new.equipped_pm_frame_id),\n        ('instant_chat_frame', new.equipped_instant_chat_frame_id),\n        ('forum_frame', new.equipped_forum_frame_id),\n        ('action_style', new.equipped_action_style_id),\n        ('nameplate', new.equipped_nameplate_id),\n        ('profile_crest', new.equipped_profile_crest_id),\n        ('action_flourish', new.equipped_action_flourish_id),\n        ('whisper_style', new.equipped_whisper_style_id),\n        ('header_control_frame', new.equipped_header_control_frame_id),\n        ('left_panel_frame', new.equipped_left_panel_frame_id),\n        ('right_panel_frame', new.equipped_right_panel_frame_id),\n        ('centre_panel_frame', new.equipped_centre_panel_frame_id),\n        ('location_frame', new.equipped_location_frame_id),\n        ('location_atmosphere', new.equipped_location_atmosphere_id)\n    ) as slots(expected_category, cosmetic_id)\n  loop\n    if slot.cosmetic_id is null then\n      continue;\n    end if;\n\n    select category\n    into actual_category\n    from public.cosmetic_items\n    where id = slot.cosmetic_id\n      and is_active = true;\n\n    if actual_category is distinct from slot.expected_category then\n      raise exception 'Cosmetic % does not belong in slot %',\n        slot.cosmetic_id,\n        slot.expected_category;\n    end if;\n\n    select exists (\n      select 1\n      from public.character_cosmetic_entitlements e\n      where e.character_id = new.character_id\n        and e.cosmetic_item_id = slot.cosmetic_id\n        and e.enabled = true\n    )\n    into owned;\n\n    if not owned then\n      raise exception 'Character does not own cosmetic %',\n        slot.cosmetic_id;\n    end if;\n  end loop;\n\n  return new;\nend;\n$$;\n\ndrop trigger if exists validate_extended_cosmetic_preferences\n  on public.character_cosmetic_preferences;\n\ncreate trigger validate_extended_cosmetic_preferences\nbefore insert or update\non public.character_cosmetic_preferences\nfor each row\nexecute function public.validate_extended_cosmetic_preferences();\n\ncreate or replace function public.unequip_revoked_extended_cosmetic()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if new.enabled = true then\n    return new;\n  end if;\n\n  update public.character_cosmetic_preferences\n  set\n    equipped_sheet_frame_id = case when equipped_sheet_frame_id = new.cosmetic_item_id then null else equipped_sheet_frame_id end,\n    equipped_chat_frame_id = case when equipped_chat_frame_id = new.cosmetic_item_id then null else equipped_chat_frame_id end,\n    equipped_portrait_frame_id = case when equipped_portrait_frame_id = new.cosmetic_item_id then null else equipped_portrait_frame_id end,\n    equipped_profile_background_id = case when equipped_profile_background_id = new.cosmetic_item_id then null else equipped_profile_background_id end,\n    equipped_pm_frame_id = case when equipped_pm_frame_id = new.cosmetic_item_id then null else equipped_pm_frame_id end,\n    equipped_instant_chat_frame_id = case when equipped_instant_chat_frame_id = new.cosmetic_item_id then null else equipped_instant_chat_frame_id end,\n    equipped_forum_frame_id = case when equipped_forum_frame_id = new.cosmetic_item_id then null else equipped_forum_frame_id end,\n    equipped_action_style_id = case when equipped_action_style_id = new.cosmetic_item_id then null else equipped_action_style_id end,\n    equipped_nameplate_id = case when equipped_nameplate_id = new.cosmetic_item_id then null else equipped_nameplate_id end,\n    equipped_profile_crest_id = case when equipped_profile_crest_id = new.cosmetic_item_id then null else equipped_profile_crest_id end,\n    equipped_action_flourish_id = case when equipped_action_flourish_id = new.cosmetic_item_id then null else equipped_action_flourish_id end,\n    equipped_whisper_style_id = case when equipped_whisper_style_id = new.cosmetic_item_id then null else equipped_whisper_style_id end,\n    equipped_header_control_frame_id = case when equipped_header_control_frame_id = new.cosmetic_item_id then null else equipped_header_control_frame_id end,\n    equipped_left_panel_frame_id = case when equipped_left_panel_frame_id = new.cosmetic_item_id then null else equipped_left_panel_frame_id end,\n    equipped_right_panel_frame_id = case when equipped_right_panel_frame_id = new.cosmetic_item_id then null else equipped_right_panel_frame_id end,\n    equipped_centre_panel_frame_id = case when equipped_centre_panel_frame_id = new.cosmetic_item_id then null else equipped_centre_panel_frame_id end,\n    equipped_location_frame_id = case when equipped_location_frame_id = new.cosmetic_item_id then null else equipped_location_frame_id end,\n    equipped_location_atmosphere_id = case when equipped_location_atmosphere_id = new.cosmetic_item_id then null else equipped_location_atmosphere_id end,\n    updated_at = now()\n  where character_id = new.character_id;\n\n  return new;\nend;\n$$;\n\ndrop trigger if exists unequip_revoked_extended_cosmetic\n  on public.character_cosmetic_entitlements;\n\ncreate trigger unequip_revoked_extended_cosmetic\nafter insert or update of enabled\non public.character_cosmetic_entitlements\nfor each row\nexecute function public.unequip_revoked_extended_cosmetic();\n")

